command -v python3>/dev/null||exit 127;T=${TYPE:-text};V=${VALUE:-${1:-}};B=${BASE_URI:-};python3 -c 'import sys,json,base64,functools;t,v,b=sys.argv[1:4];c=("t:"+v) if t=="text" else ("j:"+json.dumps(json.loads(v),ensure_ascii=False,sort_keys=True,separators=(",",":"),allow_nan=False) if t=="json" else ("b:"+base64.b64encode(base64.b64decode(v,validate=True)).decode() if t=="bytes" else (_ for _ in ()).throw(ValueError("TYPE=text|json|bytes"))));g=functools.reduce(lambda a,x:a*257+x+1,c.encode(),1);a=(b.rstrip("/") if b else "")+"/object/"+str(g);print(json.dumps({"type":t,"canonical":c,"GOBJECT":str(g),"utm_address":a},ensure_ascii=False,separators=(",",":")))' "$T" "$V" "$B"